// Injected by Usin (brand kit, edited in the IDE). Do not edit.
const icon = "data:image/svg+xml;base64,";
export const brand = {
  "name": "Être dans la lumière",
  "tagline": "Ouvrir une porte vers la libération",
  "description": "Anne Kételair, thérapeute énergéticienne à Bailleul : soins énergétiques, Reiki, numérologie et méditations, au cabinet ou à distance. Réservez en ligne.",
  "colors": {
    "primary": "#4f46e5",
    "accent": "#f59e0b",
    "background": "#ffffff"
  },
  "font": "Nunito",
  "logo": icon,
  "darkMode": "auto",
  "languages": [
    "fr",
    "en",
    "nl"
  ],
  "legal": {
    "company": "Etre dans la lumière",
    "address": "Place Abbé César Renard, 31, 7730 Bailleul (Estaimpuis)",
    "companyId": "",
    "vat": "",
    "email": "anne@etredanslalumiere.be",
    "phone": "+32495933704"
  },
  "dark": {
    "primary": "#9590ef",
    "accent": "#f59e0b",
    "background": "#100f1c"
  },
  "icon": icon,
  "symbol": "data:image/svg+xml;base64,"
} as const;

if (typeof document !== "undefined") {
  // A stylesheet (not inline styles): if the app removes or clears an override of --brand,
  // the kit colors still apply. Inline overrides set by the app win over it.
  let style = document.getElementById("msf-brand") as HTMLStyleElement | null;
  if (!style) {
    style = document.createElement("style");
    style.id = "msf-brand";
    document.head.appendChild(style);
  }
  style.textContent =
    ":root{--brand:" + brand.colors.primary + ";--brand-accent:" + brand.colors.accent + ";--brand-bg:" + brand.colors.background +
    ";--brand-font:" + "\"Nunito\", system-ui, sans-serif" + "}html:root{font-family:var(--brand-font)}" +
    // Apps often style with --primary: follow the brand unless the app defines it (zero specificity).
    ":where(:root){--primary:var(--brand)}" +
    // Dark mode (computed from the brand): only when the app is set to follow the system.
    ":root.dark{--brand:" + brand.dark.primary + ";--brand-accent:" + brand.dark.accent + ";--brand-bg:" + brand.dark.background + "}";
  // Tailwind dark: classes follow the .dark class (so "off" really means light, whatever the system).
  if (!document.getElementById("msf-dark-variant")) {
    const variant = document.createElement("style");
    variant.id = "msf-dark-variant";
    variant.type = "text/tailwindcss";
    variant.textContent = "@custom-variant dark (&:where(.dark, .dark *));";
    document.head.appendChild(variant);
  }
  const media = window.matchMedia("(prefers-color-scheme: dark)");
  // The IDE preview can force light or dark to check both looks (message from the platform).
  let forced: "light" | "dark" | null = null;
  const isDark = () => (forced ? forced === "dark" : (brand.darkMode as string) === "auto" && media.matches);
  const applyDark = () => document.documentElement.classList.toggle("dark", isDark());
  applyDark();
  media.addEventListener?.("change", applyDark);
  // Preview options sent by the platform (IDE only): large text, slow network.
  const w = window as unknown as { __msfFetch?: typeof fetch; __msfSlow?: boolean };
  window.addEventListener("message", (e) => {
    const data = e.data as { msfTheme?: string; msfTextScale?: number; msfSlow?: boolean } | null;
    const mode = data?.msfTheme;
    if (mode === "light" || mode === "dark" || mode === "auto") {
      forced = mode === "auto" ? null : mode;
      applyDark();
    }
    if (typeof data?.msfTextScale === "number") document.documentElement.style.fontSize = data.msfTextScale === 1 ? "" : data.msfTextScale * 100 + "%";
    if (typeof data?.msfSlow === "boolean") {
      if (!w.__msfFetch) {
        const original = window.fetch.bind(window);
        w.__msfFetch = original;
        window.fetch = (async (...args: Parameters<typeof fetch>) => {
          if (w.__msfSlow) await new Promise((r) => setTimeout(r, 2000));
          return original(...args);
        }) as typeof fetch;
      }
      w.__msfSlow = data.msfSlow;
    }
  });
  // Browser bar color follows the mode.
  let theme = document.querySelector('meta[name="theme-color"]:not([media])') as HTMLMetaElement | null;
  if (!theme) {
    theme = document.createElement("meta");
    theme.name = "theme-color";
    document.head.appendChild(theme);
  }
  theme.content = isDark() ? brand.dark.background : brand.colors.primary;
  let link = document.getElementById("msf-brand-font") as HTMLLinkElement | null;
  if (!link) {
    link = document.createElement("link");
    link.id = "msf-brand-font";
    link.rel = "stylesheet";
    document.head.appendChild(link);
  }
  link.href = "https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700&display=swap";
}
